      { sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
      { sku: 'DES-HOUR', qty: 3, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 },
    ],
  };

  const removeResult = removeLine(invoice, 'DEV-HOUR');

  assert(!removeResult.ok);
  assert.equal(removeResult.error, 'NOT_DRAFT');
});

test('removeLine: preserves other properties', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert(result.ok);
  const removeResult = removeLine(result.value, 'DEV-HOUR');

  assert(removeResult.ok);
  assert.equal(removeResult.value.customerId, 'C-001');
  assert.equal(removeResult.value.issueDate, '2026-10-07');
  assert.equal(removeResult.value.status, 'draft');
});

test('removeLine: does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert(result.ok);
  const originalInvoice = JSON.parse(JSON.stringify(result.value));

  removeLine(result.value, 'DEV-HOUR');

  assert.deepEqual(result.value, originalInvoice);
});

test('removeLine: returns new invoice object', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  assert(result.ok);
  const removeResult = removeLine(result.value, 'DEV-HOUR');

  assert(removeResult.ok);
  assert.notStrictEqual(removeResult.value, result.value);
  assert.notStrictEqual(removeResult.value.lines, result.value.lines);
});

test('addLine and removeLine: chain operations', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);

  const add1Result = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });
  assert(add1Result.ok);
  assert.equal(add1Result.value.lines.length, 2);

  const add2Result = addLine(add1Result.value, { sku: 'COPY-HOUR', qty: 2 });
  assert(add2Result.ok);
  assert.equal(add2Result.value.lines.length, 3);

  const removeResult = removeLine(add2Result.value, 'DES-HOUR');
  assert(removeResult.ok);
  assert.equal(removeResult.value.lines.length, 2);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(removeResult.value.lines[1].sku, 'COPY-HOUR');
});

